import ast, sys
for fn in ["proto_migrate/stream_migration.py","proto_migrate/coordinated_migration.py",
           "proto_migrate/linked_migration.py","proto_migrate/group_migration.py",
           "proto_migrate/log_migration.py"]:
    tree = ast.parse(open(fn).read())
    imported = {}
    for node in ast.walk(tree):
        if isinstance(node, ast.ImportFrom):
            for a in node.names:
                imported[a.asname or a.name] = node.lineno
        elif isinstance(node, ast.Import):
            for a in node.names:
                imported[(a.asname or a.name).split(".")[0]] = node.lineno
    src = open(fn).read()
    unused = [n for n in imported if n not in ("annotations",) and
              all(src.count(n) <= 1 for _ in (0,))]
    # crude: count name occurrences beyond import line
    real = [n for n in imported
            if sum(isinstance(x, ast.Name) and x.id == n
                   for x in ast.walk(tree))
             + sum(isinstance(x, ast.Attribute)
                   for x in ast.walk(tree)) == 0]
    # better: count ast.Name uses
    used_names = {x.id for x in ast.walk(tree) if isinstance(x, ast.Name)}
    u = [n for n in imported if n not in used_names]
    if u: print(fn, "unused:", u)
print("import scan done")
EOF
